import type { User } from "@/lib/contracts/session";
import type { UserSettings } from "@/lib/contracts/engine";

export const DEFAULT_SETTINGS: UserSettings = {
  sound: true,
  volume: 0.4,
  theme: "frost",
  soundPack: "soft-chimes",
  guardrails: { enabled: false, mode: "balanced" },
};

export function newUser(anonId: string, now = Date.now()): User {
  return {
    anonId,
    createdAt: now,
    xp: 0,
    level: 1,
    unlocks: { themes: ["frost"], soundPacks: ["soft-chimes"] },
    settings: structuredClone(DEFAULT_SETTINGS),
  };
}
/**
 * Store factory. Track E: return RedisStore when Upstash env vars are present
 * (KV_REST_API_URL/KV_REST_API_TOKEN or UPSTASH_REDIS_REST_URL/UPSTASH_REDIS_REST_TOKEN), else MemoryStore.
 */
import type { Store } from "@/lib/contracts/store";
import { MemoryStore } from "./memory";

const globalForStore = globalThis as unknown as { __colearnStore?: Store };

export function getStore(): Store {
  globalForStore.__colearnStore ??= new MemoryStore();
  return globalForStore.__colearnStore;
}
/** In-process Store for tests and local dev without Redis. Not durable; per server instance. */
import type { Store, UsageScope } from "@/lib/contracts/store";
import type { ConceptMastery, MasteryMap } from "@/lib/contracts/engine";
import type { ApiMessages, AppEvent, BossState, MomentRecord, Session, SessionSummary, TranscriptItem, User } from "@/lib/contracts/session";

const clone = <T,>(v: T): T => structuredClone(v);
const today = () => new Date().toISOString().slice(0, 10);
const scopeKey = (s: UsageScope) => `${s.kind}:${s.kind === "global" ? "all" : s.id}:${today()}`;

export class MemoryStore implements Store {
  private users = new Map<string, User>();
  private sessions = new Map<string, Session>();
  private userSessions = new Map<string, string[]>();
  private apiMessages = new Map<string, ApiMessages>();
  private transcripts = new Map<string, TranscriptItem[]>();
  private moments = new Map<string, Map<string, MomentRecord>>();
  private bosses = new Map<string, BossState>();
  private mastery = new Map<string, MasteryMap>();
  private usage = new Map<string, number>();
  readonly events: AppEvent[] = [];

  async getUser(anonId: string) { const u = this.users.get(anonId); return u ? clone(u) : null; }
  async putUser(user: User) { this.users.set(user.anonId, clone(user)); }

  async listSessions(anonId: string): Promise<SessionSummary[]> {
    return (this.userSessions.get(anonId) ?? [])
      .map((id) => this.sessions.get(id))
      .filter((s): s is Session => !!s)
      .map((s) => ({ id: s.id, title: s.title, createdAt: s.createdAt, status: s.status }))
      .sort((a, b) => b.createdAt - a.createdAt);
  }
  async getSession(id: string) { const s = this.sessions.get(id); return s ? clone(s) : null; }
  async putSession(session: Session) {
    this.sessions.set(session.id, clone(session));
    const list = this.userSessions.get(session.anonId) ?? [];
    if (!list.includes(session.id)) this.userSessions.set(session.anonId, [...list, session.id]);
  }

  async getApiMessages(id: string) { return clone(this.apiMessages.get(id) ?? []); }
  async putApiMessages(id: string, messages: ApiMessages) { this.apiMessages.set(id, clone(messages)); }

  async getTranscript(id: string) { return clone(this.transcripts.get(id) ?? []); }
  async putTranscript(id: string, items: TranscriptItem[]) { this.transcripts.set(id, clone(items)); }

  async getMoment(sessionId: string, momentId: string) {
    const m = this.moments.get(sessionId)?.get(momentId); return m ? clone(m) : null;
  }
  async listMoments(sessionId: string) {
    return [...(this.moments.get(sessionId)?.values() ?? [])].map(clone).sort((a, b) => a.createdAt - b.createdAt);
  }
  async putMoment(moment: MomentRecord) {
    const map = this.moments.get(moment.sessionId) ?? new Map<string, MomentRecord>();
    map.set(moment.id, clone(moment));
    this.moments.set(moment.sessionId, map);
  }

  async getBoss(sessionId: string, bossId: string) {
    const b = this.bosses.get(`${sessionId}:${bossId}`); return b ? clone(b) : null;
  }
  async putBoss(boss: BossState) { this.bosses.set(`${boss.sessionId}:${boss.id}`, clone(boss)); }

  async getMastery(anonId: string) { return clone(this.mastery.get(anonId) ?? {}); }
  async putMastery(anonId: string, concept: string, m: ConceptMastery) {
    this.mastery.set(anonId, { ...(this.mastery.get(anonId) ?? {}), [concept]: clone(m) });
  }

  async addUsage(scopes: UsageScope[], microUsd: number) {
    return scopes.map((s) => {
      const k = scopeKey(s); const v = (this.usage.get(k) ?? 0) + microUsd; this.usage.set(k, v); return v;
    });
  }
  async getUsage(scopes: UsageScope[]) { return scopes.map((s) => this.usage.get(scopeKey(s)) ?? 0); }

  async logEvent(event: AppEvent) { this.events.push(clone(event)); }
}
/**
 * Anonymous identity via a server-set HttpOnly cookie (survives Safari's 7-day script-storage purge).
 * Track E may extend (e.g. IP extraction helpers live in lib/platform/).
 */
import { cookies } from "next/headers";
import { ANON_COOKIE } from "@/lib/contracts/api";

const SIXTY_DAYS_S = 60 * 24 * 60 * 60;

export async function readAnonId(): Promise<string | null> {
  const value = (await cookies()).get(ANON_COOKIE)?.value;
  return value && /^[0-9a-f-]{36}$/i.test(value) ? value : null;
}

/** Returns the existing anon ID or creates one and sets the cookie (Route Handlers / Server Functions only). */
export async function ensureAnonId(): Promise<string> {
  const existing = await readAnonId();
  const id = existing ?? crypto.randomUUID();
  (await cookies()).set({
    name: ANON_COOKIE,
    value: id,
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: SIXTY_DAYS_S, // refreshed on each unlock (sliding)
  });
  return id;
}

export function clientIp(request: Request): string {
  const fwd = request.headers.get("x-forwarded-for");
  return (fwd?.split(",")[0] ?? request.headers.get("x-real-ip") ?? "unknown").trim();
}
/**
 * P0 STAND-IN — Track E replaces with Upstash rate limits + daily spend caps
 * ($5/browser, $25/IP, $75/day global; docs/design-plan.md §11).
 */
import type Anthropic from "@anthropic-ai/sdk";

export type LimitCheck = { ok: true } | { ok: false; code: "rate_limited" | "spend_cap"; message: string };

/** Call before every Claude-backed request. */
export async function checkLimits(_anonId: string, _ip: string): Promise<LimitCheck> {
  return { ok: true };
}

/** Call after every Claude response with its usage, to accumulate spend. */
export async function recordUsage(_anonId: string, _ip: string, _model: string, _usage: Anthropic.Usage | Anthropic.Beta.BetaUsage): Promise<void> {}
/**
 * Model routing — the single place to change models/effort (and the seam for model-agnosticism, P1).
 * Decisions: docs/decision-log.md (high effort for planning, medium for per-turn execution).
 */
export type Effort = "low" | "medium" | "high" | "xhigh" | "max";

export interface ModelRoute {
  model: string;
  effort: Effort;
  maxTokens: number;
}

export const MODELS = {
  /** Per-turn work loop (streams, runs code, proposes moments). Fallback: claude-opus-5-5. */
  work: { model: "claude-sonnet-5-5", effort: "medium", maxTokens: 32000 },
  /** Background session sketch after intent (planning). */
  sketch: { model: "claude-opus-5-5", effort: "high", maxTokens: 16000 },
  /** Boss generation (planning-grade). Upgrade to Opus if quality is weak. */
  boss: { model: "claude-sonnet-5-5", effort: "high", maxTokens: 16000 },
  story: { model: "claude-sonnet-5-5", effort: "medium", maxTokens: 8000 },
  wrapup: { model: "claude-sonnet-5-5", effort: "medium", maxTokens: 8000 },
  /** Fast structured calls. Switch grade to Sonnet if testing shows mis-grades. */
  grade: { model: "claude-haiku-5-5", effort: "low", maxTokens: 4000 },
  verify: { model: "claude-haiku-5-5", effort: "low", maxTokens: 4000 },
  compact: { model: "claude-haiku-5-5", effort: "low", maxTokens: 4000 },
} as const satisfies Record<string, ModelRoute>;

/** $ per million tokens (input, output, cache read) — for spend caps. Source: claude-api skill cache 2026-10-06. */
export const PRICES: Record<string, { input: number; output: number; cacheRead: number; cacheWrite: number }> = {
  "claude-opus-5-5": { input: 4, output: 20, cacheRead: 0.2, cacheWrite: 5 },
  "claude-sonnet-5-5": { input: 2, output: 10, cacheRead: 0.2, cacheWrite: 2.5 },
  "claude-haiku-5-5": { input: 0.1, output: 0.5, cacheRead: 0.01, cacheWrite: 0.125 },
};

/** Code execution tool version used by the work loop. */
export const CODE_EXECUTION_TOOL = { type: "code_execution_20260521", name: "code_execution" } as const;
import Anthropic from "@anthropic-ai/sdk";

let client: Anthropic | null = null;

/** Server-only Anthropic client. Reads ANTHROPIC_API_KEY from the environment. */
export function anthropic(): Anthropic {
  if (typeof window !== "undefined") throw new Error("anthropic() is server-only");
  client ??= new Anthropic();
  return client;
}
/** Server → client view mappers (shared). Never leak answer keys to the browser. */
import type { MomentView } from "@/lib/contracts/moment";
import type { BossState, MomentRecord, User } from "@/lib/contracts/session";
import type { BossView, UserView } from "@/lib/contracts/api";
import { engine } from "@/lib/engine";

export function toMomentView(m: MomentRecord): MomentView {
  const revealMC = m.mcOffered;
  return {
    id: m.id,
    sessionId: m.sessionId,
    type: m.type,
    concept: m.candidate.concept,
    conceptCard: m.candidate.concept_card,
    question: m.candidate.question,
    mcOptions: revealMC ? m.candidate.mc_fallback.options : undefined,
    status: m.status,
    bossId: m.bossId,
    answer: m.answer,
    mcChoice: m.mcChoice,
    verdict: m.verdict,
    why: m.why,
    correctIndex: m.mcChoice !== undefined ? m.candidate.mc_fallback.correct_index : undefined,
    xp: m.xp,
  };
}

export function toBossView(b: BossState, moments: MomentRecord[]): BossView {
  const current = b.momentIds.find((id) => {
    const m = moments.find((x) => x.id === id);
    return m && m.status === "awaiting_answer";
  });
  return { id: b.id, name: b.name, ascii: b.ascii, intro: b.intro, hp: b.hp, maxHp: b.maxHp, momentIds: b.momentIds, currentMomentId: current, outcome: b.outcome };
}

export function toUserView(u: User): UserView {
  return { xp: u.xp, level: engine.levelFor(u.xp), unlocks: u.unlocks, settings: u.settings };
}
